import{_ as N,I as z,o as i,c as t,an as c,J as G}from"./chunks/framework.CqyM3uOJ.js";const w=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"ExpressiveSharp","text":"Modern C# syntax in LINQ expression trees","tagline":"Write null-conditional operators, switch expressions, and pattern matching in your queries — source-generated at compile time with zero runtime overhead. Works with EF Core, MongoDB, and any IQueryable provider.","actions":[{"theme":"brand","text":"Introduction","link":"/guide/introduction"},{"theme":"alt","text":"Quick Start","link":"/guide/quickstart"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/EFNext/ExpressiveSharp"}]},"features":[{"icon":"🏷️","title":"Just Add [Expressive]","details":"Decorate any property, method, or constructor with [Expressive] and the source generator does the rest — no boilerplate, no manual expression trees."},{"icon":"✨","title":"Modern C# Everywhere","details":"Null-conditional ?., switch expressions, pattern matching, string interpolation, tuples, list patterns, and more — all valid inside expression trees."},{"icon":"🌐","title":"Provider-Agnostic","details":"Works with EF Core (every provider — SQL Server, Postgres, SQLite, MySQL, Oracle, …), MongoDB, and any IQueryable. One library, every backend."},{"icon":"⚡","title":"Zero Runtime Overhead","details":"All expression trees are generated at compile time using Roslyn source generators. No reflection, no Compile(), no expression tree parsing at runtime."},{"icon":"🔗","title":"Composable by Design","details":"[Expressive] members can call other [Expressive] members. Build a library of reusable query fragments and compose them freely in any query."},{"icon":"🔄","title":"Modern Syntax in LINQ Chains","details":"IExpressiveQueryable<T> enables ?. and switch expressions directly in .Where(), .Select(), and more. Full async method support for EF Core."},{"icon":"🏗️","title":"Constructor Projections","details":"Mark a constructor with [Expressive] to project DTOs directly in queries — new OrderDto(o) translates to a full provider projection."},{"icon":"📊","title":"SQL Window Functions","details":"Ranking (ROW_NUMBER, RANK, DENSE_RANK, NTILE, PERCENT_RANK, CUME_DIST), aggregate (SUM, AVG, COUNT, MIN, MAX), and navigation (LAG, LEAD, FIRST_VALUE, LAST_VALUE, NTH_VALUE) functions with a fluent PARTITION BY / ORDER BY / frame API — via the RelationalExtensions package."},{"icon":"🔧","title":"Customizable Transformer Pipeline","details":"Built-in transformers adapt expression trees for your provider, plus plugin-contributed transformers. Implement IExpressionTreeTransformer for custom rewrites."},{"icon":"🩺","title":"Roslyn Analyzers & Code Fixes","details":"EXP0001–EXP0031 diagnostics catch projection errors at compile time. Quick-fix actions and migration fixers from Projectables included."}]},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),W={name:"index.md"};function h(j,a,l,L,F,k){const I=z("ExpressiveSample");return i(),t("div",null,[a[0]||(a[0]=c("",6)),G(I,{csharpHtml:"",tabsData:"",playgroundUrl:"/ExpressiveSharp/playground-editor#snippet=ZGIuT3JkZXJzCiAgICAuV2hlcmUobyA9PiBvLkN1c3RvbWVyLkVtYWlsICE9IG51bGwgJiYgby5Ub3RhbCgpID4gNTAwbSkKICAgIC5TZWxlY3QobyA9PiBuZXcgeyBvLklkLCBUb3RhbCA9IG8uVG90YWwoKSwgR3JhZGUgPSBvLkdyYWRlKCksIEVtYWlsID0gby5DdXN0b21lci5FbWFpbCB9KQ&setup=cHVibGljIHN0YXRpYyBjbGFzcyBPcmRlckV4dAp7CiAgICBbRXhwcmVzc2l2ZV0KICAgIHB1YmxpYyBzdGF0aWMgZGVjaW1hbCBUb3RhbCh0aGlzIE9yZGVyIG8pID0-IG8uSXRlbXMuU3VtKGkgPT4gaS5Vbml0UHJpY2UgKiBpLlF1YW50aXR5KTsKCiAgICBbRXhwcmVzc2l2ZV0KICAgIHB1YmxpYyBzdGF0aWMgc3RyaW5nIEdyYWRlKHRoaXMgT3JkZXIgbykgPT4gby5Ub3RhbCgpIHN3aXRjaAogICAgewogICAgICAgID49IDEwMDBtID0-ICJQcmVtaXVtIiwKICAgICAgICA-PSAxMDBtICA9PiAiU3RhbmRhcmQiLAogICAgICAgIF8gICAgICAgID0-ICJCdWRnZXQiLAogICAgfTsKfQ&scenario=webshop"}),a[1]||(a[1]=c("",4))])}const p=N(W,[["render",h]]);export{w as __pageData,p as default};
